export function initClubContact(doc=document){
 if(doc.querySelector('[data-club-whatsapp]'))return;
 const css=doc.createElement('link');css.rel='stylesheet';css.href='contact.css?v=20261024';doc.head.append(css);
 const manifest=doc.createElement('link');manifest.rel='manifest';manifest.href='/manifest.webmanifest';if(!doc.querySelector('link[rel=manifest]'))doc.head.append(manifest);
 const widget=doc.createElement('aside');widget.dataset.clubWhatsapp='';widget.className='club-whatsapp';widget.setAttribute('aria-label','Contactar con el club por WhatsApp');
 const button=doc.createElement('button');button.className='club-whatsapp-toggle';button.type='button';button.setAttribute('aria-label','Abrir chat de WhatsApp del club');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','club-whatsapp-panel');button.innerHTML='<svg viewBox="0 0 32 32" aria-hidden="true"><path fill="currentColor" d="M16 3a12 12 0 0 0-10.4 18l-2 8 8-2A12 12 0 1 0 16 3Zm0 2a10 10 0 1 1-4 19.2l-.5-.2-5 1.3 1.3-5-.3-.5A10 10 0 0 1 16 5Zm-4 5c-.4 0-1 .3-1.3.8-2 3.1 1.8 8.7 6.3 10.4 1.8.7 3.5-.2 3.9-1.4l.2-1.2-3.5-1.7-1.2 1.5c-1.8-.8-3.2-2-4-3.6l1.3-1.4-1.3-3.1Z"/></svg>';
 const panel=doc.createElement('section');panel.id='club-whatsapp-panel';panel.hidden=true;panel.className='club-whatsapp-panel';const heading=doc.createElement('strong');heading.textContent='WhatsApp del club';const close=doc.createElement('button');close.type='button';close.textContent='Cerrar ×';close.setAttribute('aria-label','Cerrar chat de WhatsApp');const note=doc.createElement('p');note.textContent='Escribe tu consulta y continúa la conversación con el club en WhatsApp.';const label=doc.createElement('label');label.textContent='Tu mensaje';const input=doc.createElement('textarea');input.rows=3;input.maxLength=1000;input.placeholder='Hola, quiero información del club…';label.append(input);const send=doc.createElement('a');send.className='club-whatsapp-send';send.textContent='Continuar en WhatsApp';send.target='_blank';send.rel='noopener noreferrer';
 const update=()=>send.href='https://wa.me/34605245856?text='+encodeURIComponent(input.value.trim()||'Hola, quiero información del Club Octavia VRS.');update();input.addEventListener('input',update);
 const setOpen=open=>{panel.hidden=!open;button.setAttribute('aria-expanded',String(open));if(open){window.dispatchEvent(new Event('club-contact-open'));input.focus({preventScroll:true});}};button.addEventListener('click',()=>setOpen(panel.hidden));close.addEventListener('click',()=>{setOpen(false);button.focus({preventScroll:true});});widget.addEventListener('keydown',event=>{if(event.key==='Escape'){setOpen(false);button.focus({preventScroll:true});}});panel.append(heading,close,note,label,send);widget.append(panel,button);doc.body.append(widget);
}
